function model(p) {
  // Route a request from Mumbai to London over an illustrative network of fibre links and one satellite relay.
  // BFS finds the route with the fewest hops; Dijkstra finds the route with the lowest total latency.
  const dijkstra = Math.round(p.algorithm) === 1;
  const linkDown = Math.round(p.linkDown) === 1;
  const STEP = 2.5, SRC = 'MUM', DST = 'LON';
  // x, y: illustrative map positions of each node's centre (west on the left), for renderers that place nodes by hand.
  const nodes = [
    { id: 'LON', label: 'London', x: 40, y: 160 },
    { id: 'FRA', label: 'Frankfurt', x: 250, y: 130 },
    { id: 'MRS', label: 'Marseille', x: 210, y: 290 },
    { id: 'SAT', label: 'Satellite relay', x: 520, y: -10 },
    { id: 'IST', label: 'Istanbul', x: 450, y: 180 },
    { id: 'CAI', label: 'Cairo', x: 430, y: 320 },
    { id: 'NBO', label: 'Nairobi', x: 620, y: 400 },
    { id: 'DXB', label: 'Dubai', x: 680, y: 250 },
    { id: 'MUM', label: 'Mumbai', x: 880, y: 290 }
  ];
  const DOWN = 'CAI-MRS';
  const edges = [
    ['MUM', 'SAT', 260], ['SAT', 'LON', 260], ['MUM', 'DXB', 25], ['MUM', 'NBO', 45], ['DXB', 'CAI', 30], ['DXB', 'IST', 35],
    ['NBO', 'CAI', 50], ['CAI', 'MRS', 30], ['CAI', 'FRA', 40], ['IST', 'FRA', 30], ['MRS', 'FRA', 12], ['MRS', 'LON', 12], ['FRA', 'LON', 10]
  ].map(([a, b, ms]) => ({ id: a + '-' + b, a, b, ms, down: linkDown && a + '-' + b === DOWN }));
  const name = id => nodes.find(n => n.id === id).label;
  const adj = {};
  for (const n of nodes) adj[n.id] = [];
  for (const e of edges) if (!e.down) { adj[e.a].push({ to: e.b, e }); adj[e.b].push({ to: e.a, e }); }
  // dist: hops for BFS, milliseconds for Dijkstra. prev: the edge that reached each node.
  const dist = {}, prev = {}, settled = [], steps = [];
  for (const n of nodes) dist[n.id] = null;
  dist[SRC] = 0;
  const viaNow = () => Object.fromEntries(Object.keys(prev).map(k => [k, prev[k].id]));
  // Empty lists are left out, so read them as (s.updated || []) and (s.frontier || []).
  const snap = (node, updated, note) => {
    const frontier = nodes.map(n => n.id).filter(id => dist[id] !== null && !settled.includes(id));
    steps.push(Object.assign({ i: steps.length, kind: 'settle', node, note, settled: settled.slice(), dist: Object.assign({}, dist), via: viaNow() },
      updated.length ? { updated } : {}, frontier.length ? { frontier } : {}));
  };
  const fmt = d => dijkstra ? d + ' ms' : d + (d === 1 ? ' hop' : ' hops');
  let queue = [SRC];
  while (true) {
    let cur;
    if (dijkstra) {
      const open = nodes.map(n => n.id).filter(id => dist[id] !== null && !settled.includes(id));
      if (!open.length) break;
      cur = open.reduce((b, id) => dist[id] < dist[b] ? id : b);
    } else {
      if (!queue.length) break;
      cur = queue.shift();
    }
    settled.push(cur);
    const updated = [];
    if (cur !== DST) for (const { to, e } of adj[cur]) {
      if (settled.includes(to)) continue;
      const nd = dist[cur] + (dijkstra ? e.ms : 1);
      if (dist[to] === null || (dijkstra && nd < dist[to])) {
        if (dist[to] === null && !dijkstra) queue.push(to);
        updated.push({ id: to, was: dist[to], now: nd });
        dist[to] = nd; prev[to] = e;
      }
    }
    const why = dijkstra ? 'it has the lowest latency so far (' + fmt(dist[cur]) + ')' : 'it is next in the queue (' + fmt(dist[cur]) + ' away)';
    const note = cur === DST ? name(cur) + ' is settled at ' + fmt(dist[cur]) + ': the route is final.'
      : 'Settle ' + name(cur) + ': ' + why + '. ' + (updated.length ? (dijkstra ? 'Update ' : 'Discover ') + updated.map(u => name(u.id) + (u.was === null ? '' : ' (' + u.was + ' → ' + u.now + ' ms)')).join(', ') + '.' : 'Nothing new to update.');
    snap(cur, updated.map(u => u.id), note);
    if (cur === DST) break;
  }
  const path = [DST], pathEdges = [];
  while (path[0] !== SRC) { const e = prev[path[0]]; pathEdges.unshift(e.id); path.unshift(e.a === path[0] ? e.b : e.a); }
  const cost = pathEdges.reduce((s, id) => s + edges.find(e => e.id === id).ms, 0), hops = pathEdges.length;
  const algo = dijkstra ? 'dijkstra' : 'bfs';
  steps.push({ i: steps.length, kind: 'path', node: DST, settled: settled.slice(), dist: Object.assign({}, dist), via: viaNow(),
    note: 'Trace back from London: ' + path.map(name).join(' → ') + '. ' + hops + ' hops, ' + cost + ' ms.' });
  const duration = steps.length * STEP;
  const markers = steps.map(s => s.i * STEP);
  const markerLabels = steps.map(s => s.kind === 'path' ? 'Route' : 'Step ' + (s.i + 1));
  const summary = (dijkstra ? 'Dijkstra (lowest latency)' : 'BFS (fewest hops)') + ': ' + hops + ' hops, ' + cost + ' ms' + (linkDown ? ', with Cairo–Marseille down.' : '.');
  // The other algorithm's result on the same network, for comparison on screen.
  const other = p.inner ? undefined : (r => ({ algo: r.algo, hops: r.hops, cost: r.cost, path: r.path }))(model(Object.assign({}, p, { algorithm: dijkstra ? 0 : 1, inner: 1 })));
  return { other, algo, linkDown, SRC, DST, nodes, edges, steps, path, pathEdges, cost, hops, STEP, duration, markers, markerLabels, summary, unit: dijkstra ? 'ms' : 'hops' };
}

