function check(p) {
  // Check both algorithms against a brute-force search over every simple route.
  const run = a => model(Object.assign({}, p, { algorithm: a }));
  const bfs = run(0), dj = run(1), m = Math.round(p.algorithm) === 1 ? dj : bfs;
  const up = m.edges.filter(e => !e.down);
  const valid = r => r.path[0] === r.SRC && r.path[r.path.length - 1] === r.DST && r.pathEdges.length === r.path.length - 1 &&
    r.pathEdges.every((id, k) => { const e = up.find(x => x.id === id); return e && [e.a, e.b].sort().join() === [r.path[k], r.path[k + 1]].sort().join(); }) &&
    r.cost === r.pathEdges.reduce((s, id) => s + up.find(e => e.id === id).ms, 0);
  let minMs = Infinity, minHops = Infinity;
  (function walk(at, seen, ms, hops) {
    if (at === m.DST) { minMs = Math.min(minMs, ms); minHops = Math.min(minHops, hops); return; }
    for (const e of up) { const to = e.a === at ? e.b : e.b === at ? e.a : null; if (to && !seen.has(to)) walk(to, new Set([...seen, to]), ms + e.ms, hops + 1); }
  })(m.SRC, new Set([m.SRC]), 0, 0);
  const pass = valid(bfs) && valid(dj) && dj.cost === minMs && bfs.hops === minHops && dj.cost <= bfs.cost && bfs.hops <= dj.hops;
  return { pass, detail: (m.linkDown ? 'Cairo–Marseille down' : 'all links up') + ': BFS ' + bfs.hops + ' hops / ' + bfs.cost + ' ms, Dijkstra ' + dj.hops + ' hops / ' + dj.cost + ' ms; brute force agrees (fewest hops ' + minHops + ', lowest latency ' + minMs + ' ms); both routes use only working links.' };
}
